update courses
set description = 'A practical path through HTML, CSS, responsive design, JavaScript, React, APIs, databases, testing, and deployment.',
    min_progress_pct = 80
where slug = 'full-stack-web';

insert into modules(course_id, title, position)
select c.id, module.title, module.position
from courses c
cross join (values
  ('HTML Fundamentals', 2),
  ('CSS Fundamentals', 3),
  ('Responsive Design', 4),
  ('Introduction to JavaScript', 5),
  ('DOM and Browser APIs', 6),
  ('Node.js and Express APIs', 10),
  ('Database Fundamentals', 11),
  ('Git and Developer Workflow', 12),
  ('Testing and Deployment', 13)
) as module(title, position)
where c.slug = 'full-stack-web'
  and not exists (select 1 from modules m where m.course_id = c.id and m.title = module.title);

update modules m
set position = curriculum.position
from courses c
join (values
  ('Getting Started', 1),
  ('HTML Fundamentals', 2),
  ('CSS Fundamentals', 3),
  ('Responsive Design', 4),
  ('Introduction to JavaScript', 5),
  ('DOM and Browser APIs', 6),
  ('Frontend Foundations', 7),
  ('React Essentials', 8),
  ('APIs and Deployment', 9),
  ('Node.js and Express APIs', 10),
  ('Database Fundamentals', 11),
  ('Git and Developer Workflow', 12),
  ('Testing and Deployment', 13)
) as curriculum(title, position) on true
where m.course_id = c.id
  and c.slug = 'full-stack-web'
  and m.title = curriculum.title;

insert into lessons(module_id, title, content_html, position, status)
select m.id, lesson.title, lesson.content_html, lesson.position, 'published'
from modules m
join courses c on c.id = m.course_id
cross join (values
  ('HTML Fundamentals', 'HTML documents and elements', $lesson$<h2>How an HTML page is structured</h2><p>HTML (HyperText Markup Language) describes the structure and meaning of content. An HTML document begins with a doctype, identifies its language, and separates page metadata in <code>&lt;head&gt;</code> from visible content in <code>&lt;body&gt;</code>.</p><pre><code>&lt;!doctype html&gt;\n&lt;html lang="en"&gt;\n  &lt;head&gt;&lt;meta charset="utf-8"&gt;&lt;title&gt;My page&lt;/title&gt;&lt;/head&gt;\n  &lt;body&gt;&lt;h1&gt;Hello, web!&lt;/h1&gt;&lt;/body&gt;\n&lt;/html&gt;</code></pre><p>Elements are written with tags and can contain text or other elements. Nest them in a meaningful order and close elements that require closing tags.</p>$lesson$, 1),
  ('HTML Fundamentals', 'Headings, paragraphs, and text', $lesson$<h2>Give text a clear hierarchy</h2><p>Use one clear page heading and nested headings to describe sections. A heading level represents document structure, not just a preferred font size. Use paragraphs for blocks of prose and lists for related items.</p><ul><li><code>&lt;strong&gt;</code> indicates strong importance.</li><li><code>&lt;em&gt;</code> adds emphasis.</li><li><code>&lt;blockquote&gt;</code> represents quoted content.</li></ul><p>Browsers and assistive technologies use this semantic structure to help people scan and understand a page.</p>$lesson$, 2),
  ('HTML Fundamentals', 'Links, images, and media', $lesson$<h2>Connect and illustrate information</h2><p>Use an anchor with a descriptive <code>href</code> to link to a page or section. A link label such as “Read the installation guide” is more useful than “click here.”</p><p>Images need alternative text that communicates their purpose. Use an empty <code>alt</code> value for purely decorative images so they can be skipped by screen readers. Add captions when an image needs context.</p><pre><code>&lt;a href="/courses"&gt;Browse courses&lt;/a&gt;\n&lt;img src="/team.jpg" alt="The product team at a workshop"&gt;</code></pre>$lesson$, 3),
  ('HTML Fundamentals', 'Lists, tables, and page landmarks', $lesson$<h2>Choose elements by meaning</h2><p>Use ordered lists for sequences and unordered lists when order is not important. Tables are for tabular data, with header cells that make row and column relationships clear; they are not page-layout tools.</p><p>Landmark elements such as <code>&lt;header&gt;</code>, <code>&lt;nav&gt;</code>, <code>&lt;main&gt;</code>, and <code>&lt;footer&gt;</code> help users navigate the page. Put the main page content inside one main landmark.</p>$lesson$, 4),
  ('HTML Fundamentals', 'Forms and input labels', $lesson$<h2>Build forms people can use</h2><p>Forms collect structured input. Pair each control with a visible <code>&lt;label&gt;</code>, use the appropriate input type, and provide clear instructions for required or formatted information.</p><pre><code>&lt;label for="email"&gt;Email address&lt;/label&gt;\n&lt;input id="email" name="email" type="email" required&gt;\n&lt;button type="submit"&gt;Join&lt;/button&gt;</code></pre><p>Browser validation improves convenience, but data must also be validated by the server before it is trusted.</p>$lesson$, 5),
  ('HTML Fundamentals', 'HTML accessibility and validation', $lesson$<h2>Make structure accessible</h2><p>Prefer native HTML controls and landmarks because browsers already provide keyboard behavior and accessibility information for them. Keep headings in a logical order, give controls accessible names, and ensure that links describe their destination.</p><p>Use an HTML validator to catch malformed nesting and missing attributes. Then test the page using only a keyboard and inspect it at a zoom level above 100%.</p><div class="callout">Good semantic HTML is the foundation of an accessible interface.</div>$lesson$, 6),
  ('CSS Fundamentals', 'CSS rules, selectors, and cascade', $lesson$<h2>How CSS applies styles</h2><p>A CSS rule combines a selector with declarations. Selectors target elements, classes, or relationships; declarations set properties such as color, spacing, and layout.</p><pre><code>.notice {\n  color: #234;\n  padding: 1rem;\n  border-radius: .75rem;\n}</code></pre><p>When several rules match, the cascade considers origin, importance, specificity, and source order. Prefer clear classes over increasingly specific selectors.</p>$lesson$, 1),
  ('CSS Fundamentals', 'Colors, units, and typography', $lesson$<h2>Choose readable visual styles</h2><p>CSS color values can use hex, RGB, HSL, or named colors. Use relative units such as <code>rem</code> for typography and spacing that should scale with user preferences; use percentages or viewport constraints for flexible dimensions.</p><p>Choose readable line lengths and adequate line height. Check text contrast against its background so interface content remains legible.</p>$lesson$, 2),
  ('CSS Fundamentals', 'The box model and spacing', $lesson$<h2>Understand element size</h2><p>Each element has content, padding, border, and margin. With <code>box-sizing: border-box</code>, the declared width includes padding and border, which makes sizing easier to reason about.</p><p>Use padding for space inside a component and margin or layout gaps for space between components. A consistent spacing scale helps a page feel coherent.</p><pre><code>*, *::before, *::after { box-sizing: border-box; }\n.card { padding: 1.25rem; border: 1px solid #ddd; }</code></pre>$lesson$, 3),
  ('CSS Fundamentals', 'Flexbox for one-dimensional layouts', $lesson$<h2>Arrange items with Flexbox</h2><p>Flexbox is useful when arranging a row or column of items. Set a flex container, choose its direction, and use alignment and gap properties to control spacing without adding layout-only markup.</p><ul><li><code>justify-content</code> distributes items along the main axis.</li><li><code>align-items</code> aligns items along the cross axis.</li><li><code>flex-wrap</code> lets items move onto another line.</li></ul>$lesson$, 4),
  ('CSS Fundamentals', 'CSS Grid for two-dimensional layouts', $lesson$<h2>Create page grids</h2><p>CSS Grid controls rows and columns together, making it useful for dashboards, galleries, and page shells. Define columns with flexible units such as <code>fr</code>, and use <code>minmax()</code> to set sensible size limits.</p><pre><code>.cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));\n  gap: 1rem;\n}</code></pre><p>Grid and Flexbox can be combined: use Grid for the overall page and Flexbox inside a card.</p>$lesson$, 5),
  ('CSS Fundamentals', 'States, focus, and maintainable styles', $lesson$<h2>Style interactive states</h2><p>Interactive controls need visible hover and keyboard-focus states. Use <code>:focus-visible</code> to provide a clear outline when someone navigates using a keyboard, and do not remove outlines without a visible replacement.</p><p>Keep styles maintainable by using consistent naming, shared design tokens, and small reusable component classes. Avoid relying on hover alone to communicate important information.</p>$lesson$, 6),
  ('Responsive Design', 'Viewport, mobile-first, and breakpoints', $lesson$<h2>Start with a small screen</h2><p>Responsive design adapts content to the available space. A viewport meta tag tells mobile browsers to use the device width rather than rendering a scaled desktop canvas.</p><pre><code>&lt;meta name="viewport" content="width=device-width, initial-scale=1"&gt;</code></pre><p>Start with the smallest useful layout, then add breakpoints where content needs a different arrangement. Choose breakpoints based on the design, not on a list of device models.</p>$lesson$, 1),
  ('Responsive Design', 'Fluid layouts and responsive images', $lesson$<h2>Let content adapt naturally</h2><p>Use flexible containers, percentage widths, and maximum widths to keep content comfortable across screen sizes. Avoid fixed widths that cause horizontal scrolling on narrow displays.</p><p>Images should scale within their container. For different image sizes, the <code>srcset</code> and <code>sizes</code> attributes let the browser select an appropriate resource.</p><pre><code>img { max-width: 100%; height: auto; }</code></pre>$lesson$, 2),
  ('Responsive Design', 'Responsive navigation and touch targets', $lesson$<h2>Design navigation for all input types</h2><p>On smaller screens, a wide navigation can become a compact menu or a horizontally scrollable tab bar. Keep the active location visible and ensure each control remains reachable by keyboard and touch.</p><p>Provide comfortably sized tap targets and enough spacing to prevent accidental activation. Do not make hover the only way to reveal a menu or an action.</p>$lesson$, 3),
  ('Responsive Design', 'Test responsive behavior', $lesson$<h2>Verify the experience at different sizes</h2><p>Use browser developer tools to inspect narrow, medium, and wide viewports. Check for clipped content, horizontal page scrolling, tiny text, and controls that are difficult to tap.</p><p>Resize the viewport gradually around breakpoints and test real content lengths. A layout should work for long names, error messages, and translated text—not only for ideal sample content.</p>$lesson$, 4),
  ('Introduction to JavaScript', 'Values, variables, and data types', $lesson$<h2>Represent information with JavaScript</h2><p>JavaScript programs work with values such as strings, numbers, booleans, arrays, objects, <code>null</code>, and <code>undefined</code>. Use <code>const</code> by default and <code>let</code> when a binding needs to be reassigned.</p><pre><code>const learner = { name: "Sam", lessonsCompleted: 3 };\nlet isEnrolled = true;</code></pre><p>Choose descriptive names and keep data in the simplest structure that communicates its purpose.</p>$lesson$, 1),
  ('Introduction to JavaScript', 'Operators, conditions, and loops', $lesson$<h2>Express decisions and repetition</h2><p>Comparison and logical operators let a program choose what to do. Use strict equality (<code>===</code>) to avoid surprising type coercion, and make branches handle meaningful cases explicitly.</p><p>Loops and array methods such as <code>map</code>, <code>filter</code>, and <code>find</code> process collections. Prefer the form that makes the transformation easiest to read.</p>$lesson$, 2),
  ('Introduction to JavaScript', 'Functions and scope', $lesson$<h2>Package reusable behavior</h2><p>Functions accept parameters and can return results. Arrow functions are concise callbacks, while named functions can make complex operations easier to understand and debug.</p><pre><code>function completionPercent(done, total) {\n  if (total === 0) return 0;\n  return Math.round((done / total) * 100);\n}</code></pre><p>Scope determines where a variable can be accessed. Keep values close to where they are used to reduce unexpected interactions.</p>$lesson$, 3),
  ('Introduction to JavaScript', 'Arrays, objects, and useful methods', $lesson$<h2>Work with collections</h2><p>Arrays represent ordered collections, while objects group named properties. Use array methods to derive new views of data instead of mutating shared data unexpectedly.</p><pre><code>const published = lessons.filter(lesson => lesson.published);\nconst titles = published.map(lesson => lesson.title);</code></pre><p>When updating nested application data, make the intended changes explicit and preserve values that should remain unchanged.</p>$lesson$, 4),
  ('Introduction to JavaScript', 'Modules and error handling', $lesson$<h2>Organize code into modules</h2><p>ES modules share functionality using <code>export</code> and <code>import</code>. Split code around clear responsibilities so a module can be understood and tested without loading an entire application.</p><p>Use <code>try</code>/<code>catch</code> when an operation can fail and the program can provide a useful recovery path. Do not hide errors with empty catch blocks or success-shaped fallback values.</p>$lesson$, 5),
  ('Introduction to JavaScript', 'Promises and async/await', $lesson$<h2>Work with asynchronous operations</h2><p>Network requests and other I/O complete later. A Promise represents a future result; <code>async</code> and <code>await</code> make asynchronous code read in a sequential style.</p><pre><code>async function loadCourses() {\n  const response = await fetch("/api/courses");\n  if (!response.ok) throw new Error("Could not load courses");\n  return response.json();\n}</code></pre><p>Show loading and error feedback in the interface while asynchronous work is happening.</p>$lesson$, 6),
  ('DOM and Browser APIs', 'Select and update page elements', $lesson$<h2>Understand the Document Object Model</h2><p>The DOM is the browser's object representation of an HTML document. JavaScript can select elements and update their content or attributes when an interaction requires it.</p><p>In component frameworks such as React, let the framework update the DOM from state instead of directly changing nodes. Direct manipulation is still useful for understanding browser behavior and small progressive-enhancement tasks.</p>$lesson$, 1),
  ('DOM and Browser APIs', 'Events and accessible interactions', $lesson$<h2>Respond to user events</h2><p>Events represent actions such as clicks, key presses, input changes, and form submissions. Use semantic buttons and links so the browser supplies expected keyboard behavior.</p><p>When listening for a form submit, prevent the default navigation only when the application handles the submission itself. Give users clear confirmation or validation feedback.</p>$lesson$, 2),
  ('DOM and Browser APIs', 'Forms, validation, and browser storage', $lesson$<h2>Use browser features carefully</h2><p>HTML input types and constraint validation can guide users while they enter data. Always validate important data again at the server boundary.</p><p>Local storage can preserve non-sensitive preferences between visits. Do not store passwords, access tokens, or private student information in browser storage unless a carefully designed security model requires it.</p>$lesson$, 3),
  ('DOM and Browser APIs', 'Debug with browser developer tools', $lesson$<h2>Investigate browser behavior</h2><p>The console shows runtime errors and useful diagnostic messages. The Elements panel helps inspect rendered HTML and computed CSS; the Network panel helps inspect requests, status codes, and response data.</p><p>Reproduce a problem, identify the first relevant error, and test a small hypothesis. Remove temporary logs and never paste credentials or private data into shared debugging output.</p>$lesson$, 4),
  ('Node.js and Express APIs', 'Node.js runtime and package management', $lesson$<h2>Run JavaScript on the server</h2><p>Node.js runs JavaScript outside the browser and provides APIs for files, networking, and processes. A package manager installs dependencies and records them in a manifest and lockfile.</p><p>Keep secrets in environment variables supplied by the runtime. Pin and review dependencies, and do not commit private keys or production credentials.</p>$lesson$, 1),
  ('Node.js and Express APIs', 'Create routes with Express', $lesson$<h2>Build an HTTP API</h2><p>Express maps HTTP methods and paths to request handlers. A route reads validated input, performs application work, and responds with an appropriate status code and representation.</p><pre><code>app.get("/api/health", (req, res) => {\n  res.json({ status: "ok" });\n});</code></pre><p>Keep routing, business rules, and data access organized so changes remain testable.</p>$lesson$, 2),
  ('Node.js and Express APIs', 'Validate requests and handle errors', $lesson$<h2>Protect API boundaries</h2><p>Client input is untrusted, even if the user interface performs validation. Check required fields, types, lengths, and allowed values on the server before processing a request.</p><p>Return clear client errors for invalid input and avoid exposing stack traces, database credentials, or internal details in public responses. Centralize error handling so failures are logged consistently.</p>$lesson$, 3),
  ('Node.js and Express APIs', 'Authentication and authorization basics', $lesson$<h2>Know who is making a request</h2><p>Authentication establishes a user's identity. Authorization decides whether that identity may access a particular resource or perform an action.</p><p>Check access on the server for every protected operation. A hidden button is not an access control. Use established identity providers and well-reviewed session or token patterns instead of inventing password storage.</p>$lesson$, 4),
  ('Database Fundamentals', 'Relational tables and relationships', $lesson$<h2>Model application data</h2><p>Relational databases store records in tables with defined columns. Primary keys identify rows, and foreign keys express relationships between tables.</p><p>Normalize related data to reduce duplication, then use joins to retrieve a useful view. Use constraints to protect rules such as required values and unique identifiers.</p>$lesson$, 1),
  ('Database Fundamentals', 'SQL queries, filters, and joins', $lesson$<h2>Retrieve data with SQL</h2><p><code>SELECT</code> retrieves columns, <code>WHERE</code> filters rows, and <code>ORDER BY</code> controls result order. Joins combine related records through their keys.</p><pre><code>select courses.title, enrollments.status\nfrom enrollments\njoin courses on courses.id = enrollments.course_id\nwhere enrollments.student_id = $1;</code></pre><p>Use parameterized values rather than building SQL by concatenating user input.</p>$lesson$, 2),
  ('Database Fundamentals', 'Insert, update, and delete safely', $lesson$<h2>Change persisted records</h2><p><code>INSERT</code> creates rows, <code>UPDATE</code> changes selected rows, and <code>DELETE</code> removes them. Always check the target condition of an update or delete before running it.</p><p>Transactions group related changes so they can commit together or roll back together. Choose foreign-key deletion behavior carefully to preserve useful history.</p>$lesson$, 3),
  ('Database Fundamentals', 'Migrations, indexes, and access rules', $lesson$<h2>Evolve a database safely</h2><p>A migration records a versioned schema change so development, test, and production databases can move forward consistently. Make migrations repeatable where appropriate and test them against realistic data.</p><p>Indexes can speed up common lookups but add cost to writes. Row-level security and server authorization rules should follow least privilege and be tested with each user role.</p>$lesson$, 4),
  ('Git and Developer Workflow', 'Commits, branches, and collaboration', $lesson$<h2>Track changes with Git</h2><p>Git records project history in commits. Make focused commits with clear messages so teammates can understand why a change was made.</p><p>Branches provide an isolated line of work. Pull or merge changes regularly, resolve conflicts carefully, and review a diff before sharing it.</p>$lesson$, 1),
  ('Git and Developer Workflow', 'Code review and debugging workflow', $lesson$<h2>Improve code through feedback</h2><p>Code review checks correctness, clarity, tests, accessibility, and maintainability. Keep changes small enough to review and describe how you verified them.</p><p>For a bug, reproduce it, inspect relevant logs and state, form a focused hypothesis, and verify the correction with a regression test.</p>$lesson$, 2),
  ('Git and Developer Workflow', 'Environment variables and project hygiene', $lesson$<h2>Keep projects safe and reproducible</h2><p>Use environment variables for deployment-specific configuration, and commit an example file with placeholder names—not real values. Add secret files and generated output to the ignore rules.</p><p>Document setup steps and useful commands so another developer can run the project reliably.</p>$lesson$, 3),
  ('Testing and Deployment', 'Unit and integration testing', $lesson$<h2>Check behavior with tests</h2><p>Unit tests verify a small function or component in isolation. Integration tests check that connected parts work together, such as an API route with a database client.</p><p>Write assertions about observable behavior, include important error cases, and keep test data predictable. Tests complement—not replace—review and manual exploration.</p>$lesson$, 1),
  ('Testing and Deployment', 'Production builds and deployment', $lesson$<h2>Prepare an application for production</h2><p>A production build bundles and optimizes application assets. Run type checks and automated tests before deploying, and use a preview environment to validate the built application.</p><p>Configure environment values in the hosting platform. Confirm the correct build command, output directory, routing behavior, and security headers for the deployed site.</p>$lesson$, 2),
  ('Testing and Deployment', 'Monitoring, accessibility, and next steps', $lesson$<h2>Learn from a live application</h2><p>After deployment, monitor errors and performance so problems can be identified and corrected. Collect only the data you need and protect it according to your users' expectations.</p><p>Run an accessibility check, test keyboard navigation, and revisit the experience on mobile. A full-stack project is never truly finished: use feedback to prioritize the next improvement.</p>$lesson$, 3)
) as lesson(module_title, title, content_html, position)
where c.slug = 'full-stack-web'
  and m.title = lesson.module_title
  and not exists (select 1 from lessons l where l.module_id = m.id and l.title = lesson.title);
